<?php
require __DIR__.'/../shared/notification_bootstrap.php';require_once __DIR__.'/../shared/agenda_settings.php';
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
function agenda_settings_reply($code,$data){http_response_code($code);echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);exit;}
if(!permissao('perm_chamados')&&!permissao('perm_instalacao')&&!permissao('perm_config'))agenda_settings_reply(403,array('error'=>'Sem permissão.'));
$admin=permissao('perm_config');if(empty($_SESSION['suite_agenda_csrf']))$_SESSION['suite_agenda_csrf']=bin2hex(random_bytes(32));$csrf=$_SESSION['suite_agenda_csrf'];session_write_close();
try{$kind=($_GET['kind']??'ticket')==='installation'?'installation':'ticket';$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='POST'){if(!$admin)agenda_settings_reply(403,array('error'=>'É necessária permissão de configuração.'));$data=json_decode(file_get_contents('php://input',false,null,0,4096),true);if(!is_array($data)||!is_string($data['csrf']??null)||!hash_equals($csrf,$data['csrf']))agenda_settings_reply(403,array('error'=>'Sessão expirada.'));mka_agenda_settings_save($conn,$data,$kind);}elseif($method!=='GET')agenda_settings_reply(405,array('error'=>'Método inválido.'));agenda_settings_reply(200,array('lunch'=>mka_agenda_settings($conn,$kind),'csrf'=>$csrf,'can_edit'=>$admin,'today'=>(new DateTimeImmutable('now',new DateTimeZone('America/Sao_Paulo')))->format('Y-m-d')));}catch(InvalidArgumentException $e){agenda_settings_reply(422,array('error'=>$e->getMessage()));}catch(Throwable $e){agenda_settings_reply(503,array('error'=>'Não foi possível acessar a configuração da agenda.'));}
